function deviceKwh(powerW, hoursPerDay, days){ powerW=+powerW; hoursPerDay=+hoursPerDay; days=+days; return Math.round(powerW/1000*hoursPerDay*days*1000)/1000; }
function deviceCost(powerW, hoursPerDay, days, pricePerKwh){ return Math.round(deviceKwh(powerW,hoursPerDay,days)*pricePerKwh*100)/100; }
function total(costs){ var s=0; for(var i=0;i<costs.length;i++) s+=+costs[i]; return Math.round(s*100)/100; }
var EXPORTS={deviceKwh:deviceKwh, deviceCost:deviceCost, total:total};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ElectricityForgePure = EXPORTS; }
